import sys

n = int(sys.stdin.read().split()[0])
rot = {'0': '0', '1': '1', '8': '8', '2': '5', '5': '2', '6': '9', '9': '6'}
ans = 0
for x in range(1, n + 1):
    s = str(x)
    if all(c in rot for c in s) and ''.join(rot[c] for c in s) != s:
        ans += 1
print(ans)

